diff --git a/django/db/models/fields/json.py b/django/db/models/fields/json.py
index 29c6ff0926..875addb954 100644
--- a/django/db/models/fields/json.py
+++ b/django/db/models/fields/json.py
@@ -368,12 +368,18 @@ class KeyTransformIsNull(lookups.IsNull):
     def as_oracle(self, compiler, connection):
         if not self.rhs:
             return HasKey(self.lhs.lhs, self.lhs.key_name).as_oracle(compiler, connection)
-        return super().as_sql(compiler, connection)
+        # key__isnull=True: match only missing keys, not JSON null values.
+        has_key_sql, _ = HasKey(self.lhs.lhs, self.lhs.key_name).as_oracle(compiler, connection)
+        return 'NOT %s' % has_key_sql, []

     def as_sqlite(self, compiler, connection):
         if not self.rhs:
             return HasKey(self.lhs.lhs, self.lhs.key_name).as_sqlite(compiler, connection)
-        return super().as_sql(compiler, connection)
+        # key__isnull=True: use JSON_TYPE IS NULL to distinguish missing keys from JSON null
+        # values (JSON_EXTRACT returns SQL NULL for both on SQLite).
+        return HasKey(self.lhs.lhs, self.lhs.key_name).as_sql(
+            compiler, connection, template='JSON_TYPE(%s, %%s) IS NULL'
+        )


